// The game's dice. Read this file: it is the whole truth about how a roll works.
//
// A roll spec looks like "3d6" (three six-sided dice) or "d20" (one twenty-sided die).
// Each die is rolled with Math.random(), JavaScript's built-in random number generator.
// Math.random() gives a number from 0 up to (but never including) 1. We scale it to the
// number of sides, throw away the decimals, and add 1 so the lowest face is 1.
//
// Math.random() is random enough for a game. It is not secure randomness, and nothing
// here pretends otherwise.
//
// Do not edit this file. The game fingerprints it, and a changed dice file means your
// hero loses everything. If you want to experiment, write your own copy somewhere else.

export const SIDES = [4, 6, 8, 10, 12, 20, 100];
const MAX_COUNT = 100;

export function parseSpec(spec) {
  const match = /^(\d+)?d(\d+)$/.exec(String(spec));
  if (!match) throw new RangeError(`Bad dice spec "${spec}". Use something like 2d6 or d20.`);
  const count = match[1] === undefined ? 1 : Number(match[1]);
  const sides = Number(match[2]);
  if (count < 1 || count > MAX_COUNT) {
    throw new RangeError(`Bad dice count in "${spec}". Roll between 1 and ${MAX_COUNT} dice.`);
  }
  if (!SIDES.includes(sides)) {
    throw new RangeError(`Bad dice sides in "${spec}". Allowed: ${SIDES.join(', ')}.`);
  }
  return { count, sides };
}

export function roll(spec, rng = Math.random) {
  const { count, sides } = parseSpec(spec);
  const results = [];
  for (let i = 0; i < count; i++) {
    results.push(Math.floor(rng() * sides) + 1);
  }
  const total = results.reduce((sum, face) => sum + face, 0);
  return { spec, count, sides, results, total };
}
